function verifyTree(t,utf8,sha1){
 if(t.truncated||!Array.isArray(t.tree))throw Error("truncated/missing tree");
 const encoded=t.tree.map(e=>({e,key:utf8(e.path+(e.type==="tree"?"/":""))})).sort((a,b)=>{const n=Math.min(a.key.length,b.key.length);for(let i=0;i<n;i++)if(a.key[i]!==b.key[i])return a.key[i]-b.key[i];return a.key.length-b.key.length});
 let b=[];for(const {e} of encoded){b.push(...utf8(e.mode.replace(/^0+/,"")+" "+e.path+"\0"));for(let i=0;i<40;i+=2)b.push(parseInt(e.sha.slice(i,i+2),16));}
 const actual=sha1(utf8("tree "+b.length+"\0").concat(b));if(actual!==t.sha)throw Error("tree SHA mismatch "+t.sha+" != "+actual);
 return {sha:t.sha,verified:true,entries:t.tree.map(({path,mode,type,sha,size})=>({path,mode,type,sha,...(size===undefined?{}:{size})}))};
}
